-- The two checklists published on 2026-11-26: The Hours Before a First Date
-- (First Dates) and Getting a Shot When Needles Scare You (Needles).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-26`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-hours-before-a-first-date', 'The Hours Before a First Date', 'Open this on the afternoon of a first date, when you have rewritten the plan four times and half want to cancel. It settles the practical parts and lowers the bar from impressive to simply having met someone.', 'First Dates', '["Pick somewhere short and public — A coffee you can leave in forty minutes beats a dinner you cannot.", "Tell one friend where you are going — A text with the place and time is basic, and it settles you.", "Confirm the time that morning — A quick message saves a wasted trip and reads as keen, not needy.", "Arrange your own way home — Your own ride means you leave when you want to.", "Have two questions you actually care about — A real question beats an interview and starts a conversation.", "Aim to find out whether you like them — Being liked is not the job of the evening, and noticing is.", "Say the awkward thing out loud — Naming the nerves early takes most of the air out of them.", "Hold off on a verdict for an hour after — First impressions are noisy and the evening deserves to settle."]'::jsonb, 'as needed', array['Social Anxiety', 'Relationships', 'Self-Esteem']::text[], 1, '2026-11-26T16:00:00+00:00'::timestamptz),
  ('getting-a-shot-when-needles-scare-you', 'Getting a Shot When Needles Scare You', 'Open this before a vaccination, a blood draw or any appointment with a needle in it, when the dread has been building for days. It lists the things you can ask for and do that make the minute itself much easier.', 'Needles', '["Say at the desk that needles are hard for you — Staff do this all day and will slow down if they know.", "Ask to lie down rather than sit — Lying flat makes feeling faint far less likely.", "Eat and drink something beforehand — Going in hungry or dry makes everything feel worse.", "Look away and pick something to study — Watching the needle gives your body more to react to.", "Breathe out slowly as it goes in — A long out-breath settles the whole system for a few seconds.", "Tense and release your legs a few times — Squeezing and releasing your muscles helps you stay steady.", "Ask for a few minutes before standing — Getting up straight away is where people come unstuck.", "Plan one small good thing for after — Something to walk toward changes what you are focused on."]'::jsonb, 'as needed', array['Anxiety', 'Body', 'Grounding']::text[], 1, '2026-11-26T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
